-- KOJAC LMS — Kanji JLPT N3 Core activation data
-- Migration 016: 120 additional high-frequency N3 Kanji after frozen KOJAC N5/N4.
-- Incremental data-only migration. Reuses learning_items + generic Kanji engine/SRS.
-- No schema/RPC/RLS/progress changes. Does not modify N5/N4 rows or user progress.
-- This is KOJAC N3 Core v1: a practical teaching set informed by common N3 study references;
-- it is NOT presented as an official immutable JLPT Kanji list.

begin;

-- Fail fast if the project baseline is not the expected frozen KOJAC N5/N4 state.
do $preflight$
declare
  v_n5_count integer;
  v_n4_count integer;
  v_wrong_level integer;
  v_existing_other_dataset integer;
begin
  if to_regclass('public.learning_items') is null then
    raise exception 'KOJAC N3 preflight: public.learning_items tidak ditemukan.';
  end if;

  if not exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='learning_items' and column_name='jlpt_level'
  ) then
    raise exception 'KOJAC N3 preflight: kolom learning_items.jlpt_level tidak ditemukan.';
  end if;

  select count(*) into v_n5_count
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N5' and li.is_published=true and li.reading is null;

  select count(*) into v_n4_count
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.is_published=true and li.reading is null;

  if v_n5_count <> 90 then
    raise exception 'KOJAC N3 preflight: baseline N5 harus 90 published Kanji, ditemukan %.', v_n5_count;
  end if;

  if v_n4_count <> 154 then
    raise exception 'KOJAC N3 preflight: baseline N4 harus 154 published Kanji, ditemukan %.', v_n4_count;
  end if;

  -- A candidate may already exist only when this same N3 migration was run successfully before.
  select count(*) into v_wrong_level
  from public.learning_items as li
  where li.item_type='kanji'
    and li.reading is null
    and li.prompt in ('合','部','彼','内','実','当','戦','性','対','関','定','政','取','所','現','最','化','民','相','法','情','向','平','成','経','信','面','連','原','顔','次','数','美','回','表','声','報','要','変','神','和','引','治','決','太','込','受','解','市','期','活','頭','組','指','説','能','葉','流','然','初','調','笑','議','直','夫','選','権','利','制','続','進','伝','加','助','点','産','務','件','命','番','付','得','好','違','殺','置','返','論','際','歳','形','光','首','勝','必','係','由','愛','都','放','過','約','馬','状','想','官','交','米','配','若','常','果','呼','共','残','判','役','他','術','支')
    and li.jlpt_level is distinct from 'N3';

  if v_wrong_level <> 0 then
    raise exception 'KOJAC N3 preflight: ditemukan % kandidat N3 yang sudah dimiliki level lain. Migration dibatalkan agar N5/N4 tidak berubah.', v_wrong_level;
  end if;

  select count(*) into v_existing_other_dataset
  from public.learning_items as li
  where li.item_type='kanji'
    and li.jlpt_level='N3'
    and li.reading is null
    and li.prompt in ('合','部','彼','内','実','当','戦','性','対','関','定','政','取','所','現','最','化','民','相','法','情','向','平','成','経','信','面','連','原','顔','次','数','美','回','表','声','報','要','変','神','和','引','治','決','太','込','受','解','市','期','活','頭','組','指','説','能','葉','流','然','初','調','笑','議','直','夫','選','権','利','制','続','進','伝','加','助','点','産','務','件','命','番','付','得','好','違','殺','置','返','論','際','歳','形','光','首','勝','必','係','由','愛','都','放','過','約','馬','状','想','官','交','米','配','若','常','果','呼','共','残','判','役','他','術','支')
    and coalesce(li.extra->>'dataset','') <> 'N3-core-v1';

  if v_existing_other_dataset <> 0 then
    raise exception 'KOJAC N3 preflight: % kandidat sudah ada sebagai N3 dari dataset lain. Tidak di-overwrite otomatis.', v_existing_other_dataset;
  end if;
end
$preflight$;

insert into public.learning_items as li (
  item_type, jlpt_level, prompt, reading, meaning_id, meaning_en, extra, is_published
)
