  ('kanji','N3','支',null,'mendukung / cabang',null,'{"sort_order":120,"category":"Aktivitas","onyomi":["シ"],"kunyomi":["ささ.える"],"stroke_count":4,"examples":[{"word":"支店","reading":"してん","meaning_id":"cabang"},{"word":"支持","reading":"しじ","meaning_id":"dukungan"},{"word":"支払い","reading":"しはらい","meaning_id":"pembayaran"},{"word":"支給","reading":"しきゅう","meaning_id":"pemberian / pembayaran"},{"word":"支援","reading":"しえん","meaning_id":"dukungan / bantuan"}],"sentences":[{"japanese":"支店について、くわしくしらべました。","reading":"してんについて、くわしくしらべました。","meaning":"Saya mencari tahu lebih detail tentang cabang."},{"japanese":"じゅぎょうで、支持についてまなびました。","reading":"じゅぎょうで、しじについてまなびました。","meaning":"Di kelas, saya mempelajari dukungan."},{"japanese":"支払いについて、しごとでせつめいをうけました。","reading":"しはらいについて、しごとでせつめいをうけました。","meaning":"Di tempat kerja, saya mendapat penjelasan tentang pembayaran."},{"japanese":"さいきん、支給にかんするニュースをみました。","reading":"さいきん、しきゅうにかんするにゅーすをみました。","meaning":"Belakangan ini saya melihat berita terkait pemberian / pembayaran."},{"japanese":"支援について、じぶんのいけんをまとめました。","reading":"しえんについて、じぶんのいけんをまとめました。","meaning":"Saya merangkum pendapat saya tentang dukungan / bantuan."}],"related_kanji":[],"mnemonic":{"kind":"learning_mnemonic","components":[],"tip":"Cara mudah mengingat: hubungkan 「支」 dengan arti “mendukung / cabang”. Gunakan 「支店」 (cabang) sebagai jangkar ingatan; ini mnemonic belajar, bukan klaim etimologi."},"curriculum":"KOJAC Kanji Core","dataset":"N3-core-v1","example_dataset":"N3-core-5x5-v1","sentence_dataset":"N3-core-5x5-v1","learning_aids_dataset":"N3-core-v1","curriculum_note":"Practical high-frequency N3 core teaching set; not an official immutable JLPT kanji list."}'::jsonb,true)
on conflict (item_type, prompt, (coalesce(reading, '')))
do nothing;

-- Validate exactly the rows owned by this incremental N3 core dataset.
do $validate$
declare
  v_count integer;
  v_orders integer;
  v_bad integer;
  v_vocab_bad integer;
  v_sentence_bad integer;
  v_vocab_duplicate integer;
  v_sentence_duplicate integer;
  v_relation_bad integer;
  v_overlap integer;
begin
  select count(*) into v_count
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1';

  if v_count <> 120 then
    raise exception 'KOJAC N3 validation failed: expected 120 N3-core-v1 rows, found %.', v_count;
  end if;

  select count(distinct (li.extra->>'sort_order')::integer) into v_orders
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1';

  if v_orders <> 120 then
    raise exception 'KOJAC N3 validation failed: sort_order harus unik untuk 120 item.';
  end if;

  select count(*) into v_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    and (
      coalesce(li.meaning_id,'')=''
      or coalesce(li.extra->>'category','')=''
      or jsonb_typeof(li.extra->'onyomi') is distinct from 'array'
      or jsonb_typeof(li.extra->'kunyomi') is distinct from 'array'
      or (jsonb_array_length(li.extra->'onyomi')=0 and jsonb_array_length(li.extra->'kunyomi')=0)
      or coalesce((li.extra->>'stroke_count')::integer,0)<=0
      or jsonb_typeof(li.extra->'examples') is distinct from 'array'
      or jsonb_typeof(li.extra->'sentences') is distinct from 'array'
      or jsonb_typeof(li.extra->'related_kanji') is distinct from 'array'
      or jsonb_typeof(li.extra->'mnemonic') is distinct from 'object'
      or coalesce(li.extra->'mnemonic'->>'tip','')=''
    );

  if v_bad <> 0 then
    raise exception 'KOJAC N3 validation failed: % row(s) memiliki metadata inti tidak lengkap.', v_bad;
  end if;

  select count(*) into v_vocab_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    and (
      jsonb_array_length(li.extra->'examples') < 5
      or exists (
        select 1
        from jsonb_array_elements(li.extra->'examples') as e
        where coalesce(e->>'word','')=''
          or coalesce(e->>'reading','')=''
          or coalesce(e->>'meaning_id','')=''
          or position(li.prompt in coalesce(e->>'word',''))=0
          or coalesce(e->>'reading','') ~ '[一-龯々]'
      )
    );

  if v_vocab_bad <> 0 then
    raise exception 'KOJAC N3 validation failed: % row(s) tidak memiliki >=5 contoh kosakata valid.', v_vocab_bad;
  end if;

  select count(*) into v_sentence_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    and (
      jsonb_array_length(li.extra->'sentences') < 5
      or exists (
        select 1
        from jsonb_array_elements(li.extra->'sentences') as s
        where coalesce(s->>'japanese','')=''
          or coalesce(s->>'reading','')=''
          or coalesce(s->>'meaning','')=''
          or position(li.prompt in coalesce(s->>'japanese',''))=0
          or coalesce(s->>'reading','') ~ '[一-龯々]'
      )
    );

  if v_sentence_bad <> 0 then
    raise exception 'KOJAC N3 validation failed: % row(s) tidak memiliki >=5 contoh kalimat valid.', v_sentence_bad;
  end if;

  select count(*) into v_vocab_duplicate
  from (
    select li.id, e->>'word' as word, e->>'reading' as reading
    from public.learning_items as li
    cross join lateral jsonb_array_elements(li.extra->'examples') as e
    where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
      and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    group by li.id, e->>'word', e->>'reading'
    having count(*) > 1
  ) as duplicated;

  if v_vocab_duplicate <> 0 then
    raise exception 'KOJAC N3 validation failed: ditemukan % duplicate contoh kosakata dalam item.', v_vocab_duplicate;
  end if;

  select count(*) into v_sentence_duplicate
  from (
    select li.id, s->>'japanese' as japanese
    from public.learning_items as li
    cross join lateral jsonb_array_elements(li.extra->'sentences') as s
    where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
      and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    group by li.id, s->>'japanese'
    having count(*) > 1
  ) as duplicated;

  if v_sentence_duplicate <> 0 then
    raise exception 'KOJAC N3 validation failed: ditemukan % duplicate contoh kalimat dalam item.', v_sentence_duplicate;
  end if;

  select count(*) into v_relation_bad
  from public.learning_items as li
  cross join lateral jsonb_array_elements(li.extra->'related_kanji') as rel
  where li.item_type='kanji' and li.jlpt_level='N3' and li.reading is null
    and li.is_published=true and li.extra->>'dataset'='N3-core-v1'
    and (
      coalesce(rel->>'kanji','')=''
      or rel->>'kanji'=li.prompt
      or coalesce(rel->>'note','')=''
      or coalesce(rel->>'relation','') not in ('same_radical','similar_shape','shared_component','concept_related')
    );

  if v_relation_bad <> 0 then
    raise exception 'KOJAC N3 validation failed: % related-kanji entry tidak valid.', v_relation_bad;
  end if;

  select count(*) into v_overlap
  from public.learning_items as n3
  join public.learning_items as lower
    on lower.item_type='kanji'
    and lower.jlpt_level in ('N5','N4')
    and lower.reading is null
    and lower.prompt=n3.prompt
  where n3.item_type='kanji' and n3.jlpt_level='N3' and n3.reading is null
    and n3.is_published=true and n3.extra->>'dataset'='N3-core-v1';

  if v_overlap <> 0 then
    raise exception 'KOJAC N3 validation failed: % duplicate prompt ditemukan antara N3 dan N5/N4.', v_overlap;
  end if;
end
$validate$;

commit;
